<?php
declare(strict_types=1);

/**
 * Flint sync store – a dumb, account-free key/value log for client state.
 *
 *   GET    /api/sync?since=<cursor>[&limit=1..1000]   → changes after <cursor>
 *   POST   /api/sync   {"records":[{kind,id,data,updatedAt}, …]}  → last-write-wins merge
 *   DELETE /api/sync                                    → wipe the whole vault
 *
 * Auth: "Authorization: Bearer <vault key>" (or "X-Flint-Vault: <vault key>").
 * The vault key is a random secret generated by the first client and shared with
 * further devices via QR code / pairing link. The server stores only its SHA-256.
 *
 * The server knows no business logic: it stores opaque JSON per (vault, kind, id)
 * and keeps the record with the highest client timestamp (updatedAt, ms).
 * Every accepted write gets a new, strictly increasing sequence number; clients
 * pull with the last sequence number they have seen ("cursor").
 */

function ff_sync_handle(): never
{
    header('Content-Type: application/json; charset=utf-8');
    header('Access-Control-Allow-Origin: *');
    header('Access-Control-Allow-Methods: GET, POST, DELETE, OPTIONS');
    header('Access-Control-Allow-Headers: Authorization, Content-Type, X-Flint-Vault');
    header('Access-Control-Max-Age: 86400');
    header('Cache-Control: no-store');
    header('X-Content-Type-Options: nosniff');

    $method = $_SERVER['REQUEST_METHOD'] ?? 'GET';
    if ($method === 'OPTIONS') {
        http_response_code(204);
        exit;
    }

    if (!FF_SYNC_ENABLED) {
        ff_sync_error('SYNC_DISABLED', 'Sync is disabled on this server (FF_SYNC_ENABLED).', 404);
    }
    if (!ff_sync_client_allowed((string)($_SERVER['REMOTE_ADDR'] ?? ''))) {
        ff_sync_error('FORBIDDEN_NETWORK', 'Sync is only available from the local network.', 403);
    }
    if (!extension_loaded('pdo_sqlite')) {
        ff_sync_error('SERVER_MISCONFIGURED', 'Enable the PHP extension pdo_sqlite for sync.', 500);
    }

    $vault = ff_sync_vault();
    $db = ff_sync_db();

    switch ($method) {
        case 'GET':
            $since = max(0, (int)($_GET['since'] ?? 0));
            $limit = max(1, min(FF_SYNC_MAX_BATCH, (int)($_GET['limit'] ?? 500)));
            ff_sync_json(ff_sync_pull($db, $vault, $since, $limit));
        case 'POST':
            ff_sync_json(ff_sync_push($db, $vault, ff_sync_body()));
        case 'DELETE':
            $st = $db->prepare('DELETE FROM records WHERE vault = ?');
            $st->execute([$vault]);
            ff_sync_json(['ok' => true, 'deleted' => $st->rowCount()]);
        default:
            ff_sync_error('METHOD_NOT_ALLOWED', 'Use GET, POST or DELETE.', 405);
    }
}

// ------------------------------------------------------------------ core

/** @return array{records:list<array>, cursor:int, more:bool, epoch:string, serverTime:int} */
function ff_sync_pull(PDO $db, string $vault, int $since, int $limit): array
{
    $st = $db->prepare('SELECT kind, id, data, updated_at, seq FROM records
                        WHERE vault = ? AND seq > ? ORDER BY seq LIMIT ?');
    $st->execute([$vault, $since, $limit + 1]);
    $rows = $st->fetchAll(PDO::FETCH_ASSOC);

    $more = count($rows) > $limit;
    if ($more) array_pop($rows);

    $records = [];
    $cursor = $since;
    foreach ($rows as $r) {
        $records[] = [
            'kind'      => $r['kind'],
            'id'        => $r['id'],
            'data'      => json_decode($r['data'], true),
            'updatedAt' => (int)$r['updated_at'],
        ];
        $cursor = (int)$r['seq'];
    }
    return ['records' => $records, 'cursor' => $cursor, 'more' => $more, 'epoch' => ff_sync_epoch($db), 'serverTime' => ff_sync_now()];
}

/** @return array{ok:true, applied:int, ignored:int, epoch:string, serverTime:int} */
function ff_sync_push(PDO $db, string $vault, array $body): array
{
    $records = $body['records'] ?? null;
    if (!is_array($records) || !array_is_list($records)) {
        ff_sync_error('INVALID_BODY', 'Expected {"records": [...]}.', 400);
    }
    if (count($records) > FF_SYNC_MAX_BATCH) {
        ff_sync_error('PAYLOAD_TOO_LARGE', 'At most ' . FF_SYNC_MAX_BATCH . ' records per request.', 413);
    }

    // Validate everything before touching the database (all-or-nothing).
    $clean = [];
    $maxTs = ff_sync_now() + FF_SYNC_MAX_CLOCK_SKEW;
    foreach ($records as $i => $r) {
        if (!is_array($r)) ff_sync_error('INVALID_RECORD', "Record $i is not an object.", 400);
        $kind = $r['kind'] ?? null;
        $id   = $r['id'] ?? null;
        $ts   = $r['updatedAt'] ?? null;
        $data = $r['data'] ?? null;
        if (!is_string($kind) || !preg_match('/^[a-z][a-z0-9_]{0,15}$/', $kind)) {
            ff_sync_error('INVALID_RECORD', "Record $i: kind must match [a-z][a-z0-9_]{0,15}.", 400);
        }
        if (!is_string($id) || $id === '' || strlen($id) > 128) {
            ff_sync_error('INVALID_RECORD', "Record $i: id must be a string of 1–128 bytes.", 400);
        }
        if (!is_int($ts) || $ts <= 0) {
            ff_sync_error('INVALID_RECORD', "Record $i: updatedAt must be a positive integer (ms).", 400);
        }
        if (!is_array($data)) {
            ff_sync_error('INVALID_RECORD', "Record $i: data must be an object.", 400);
        }
        $json = json_encode($data, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
        if ($json === false || strlen($json) > FF_SYNC_MAX_RECORD_BYTES) {
            ff_sync_error('INVALID_RECORD', "Record $i: data exceeds " . FF_SYNC_MAX_RECORD_BYTES . ' bytes.', 400);
        }
        // A client clock far in the future would win every conflict forever – clamp it.
        $clean[] = [$kind, $id, $json, min($ts, $maxTs)];
    }

    $applied = 0;
    $db->exec('BEGIN IMMEDIATE');
    try {
        $seq = (int)$db->query("SELECT v FROM meta WHERE k = 'seq'")->fetchColumn();
        $st = $db->prepare('INSERT INTO records (vault, kind, id, data, updated_at, seq)
                            VALUES (:vault, :kind, :id, :data, :ts, :seq)
                            ON CONFLICT (vault, kind, id) DO UPDATE
                              SET data = excluded.data, updated_at = excluded.updated_at, seq = excluded.seq
                              WHERE excluded.updated_at > records.updated_at');
        foreach ($clean as [$kind, $id, $json, $ts]) {
            $st->execute([':vault' => $vault, ':kind' => $kind, ':id' => $id, ':data' => $json, ':ts' => $ts, ':seq' => $seq + 1]);
            if ($st->rowCount() > 0) {
                $seq++;
                $applied++;
            }
        }
        $db->prepare("UPDATE meta SET v = ? WHERE k = 'seq'")->execute([$seq]);
        $db->exec('COMMIT');
    } catch (Throwable $e) {
        $db->exec('ROLLBACK');
        error_log('Flint sync: ' . $e->getMessage());
        ff_sync_error('SYNC_WRITE_FAILED', 'Could not store the records.', 500);
    }

    return ['ok' => true, 'applied' => $applied, 'ignored' => count($clean) - $applied, 'epoch' => ff_sync_epoch($db), 'serverTime' => ff_sync_now()];
}

// ------------------------------------------------------------------ plumbing

function ff_sync_db(): PDO
{
    $dir = dirname(FF_SYNC_DB);
    if (!is_dir($dir) && !mkdir($dir, 0775, true) && !is_dir($dir)) {
        ff_sync_error('SERVER_MISCONFIGURED', 'Sync directory is not writable.', 500);
    }
    try {
        $db = new PDO('sqlite:' . FF_SYNC_DB, null, null, [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION]);
        $db->exec('PRAGMA busy_timeout = 5000');
        $db->exec('PRAGMA journal_mode = WAL');
        $db->exec('PRAGMA synchronous = NORMAL');
        $db->exec('CREATE TABLE IF NOT EXISTS records (
                     vault      TEXT    NOT NULL,
                     kind       TEXT    NOT NULL,
                     id         TEXT    NOT NULL,
                     data       TEXT    NOT NULL,
                     updated_at INTEGER NOT NULL,
                     seq        INTEGER NOT NULL,
                     PRIMARY KEY (vault, kind, id)
                   ) WITHOUT ROWID');
        $db->exec('CREATE INDEX IF NOT EXISTS records_vault_seq ON records (vault, seq)');
        $db->exec('CREATE TABLE IF NOT EXISTS meta (k TEXT PRIMARY KEY, v INTEGER NOT NULL)');
        $db->exec("INSERT OR IGNORE INTO meta (k, v) VALUES ('seq', 0)");
        // Random id of this database: if it changes (reset/restore), clients start over at cursor 0.
        $db->exec("INSERT OR IGNORE INTO meta (k, v) VALUES ('epoch', abs(random() % 9007199254740991))");
        return $db;
    } catch (Throwable $e) {
        error_log('Flint sync: ' . $e->getMessage());
        ff_sync_error('SERVER_MISCONFIGURED', 'Sync database is not available (check that var/sync is writable).', 500);
    }
}

/** Vault id = SHA-256 of the secret key; the key itself is never stored. */
function ff_sync_vault(): string
{
    $key = '';
    $auth = (string)($_SERVER['HTTP_AUTHORIZATION'] ?? $_SERVER['REDIRECT_HTTP_AUTHORIZATION'] ?? '');
    if (preg_match('/^Bearer\s+(\S+)$/i', $auth, $m)) {
        $key = $m[1];
    } elseif (isset($_SERVER['HTTP_X_FLINT_VAULT'])) {
        $key = trim((string)$_SERVER['HTTP_X_FLINT_VAULT']);
    }
    if (!preg_match('/^[A-Za-z0-9_-]{32,128}$/', $key)) {
        ff_sync_error('UNAUTHORIZED', 'Send the vault key as "Authorization: Bearer <key>" (32–128 chars, base64url).', 401);
    }
    return hash('sha256', $key);
}

function ff_sync_body(): array
{
    $raw = file_get_contents('php://input', false, null, 0, FF_SYNC_MAX_BODY_BYTES + 1);
    if ($raw === false || $raw === '') ff_sync_error('INVALID_BODY', 'Empty request body.', 400);
    if (strlen($raw) > FF_SYNC_MAX_BODY_BYTES) ff_sync_error('PAYLOAD_TOO_LARGE', 'Request body too large.', 413);
    $body = json_decode($raw, true);
    if (!is_array($body)) ff_sync_error('INVALID_BODY', 'Body must be a JSON object.', 400);
    return $body;
}

/** true if $ip is inside one of FF_SYNC_ALLOWED_NETS (empty list = everyone). */
function ff_sync_client_allowed(string $ip): bool
{
    if (FF_SYNC_ALLOWED_NETS === []) return true;
    $addr = @inet_pton($ip);
    if ($addr === false) return false;
    // IPv4-mapped IPv6 (::ffff:a.b.c.d) → plain IPv4
    if (strlen($addr) === 16 && str_starts_with($addr, str_repeat("\0", 10) . "\xff\xff")) {
        $addr = substr($addr, 12);
    }
    foreach (FF_SYNC_ALLOWED_NETS as $cidr) {
        [$net, $bits] = array_pad(explode('/', $cidr, 2), 2, null);
        $netBin = @inet_pton((string)$net);
        if ($netBin === false || strlen($netBin) !== strlen($addr)) continue;
        $bits = $bits === null ? strlen($addr) * 8 : (int)$bits;
        $bytes = intdiv($bits, 8);
        $rest = $bits % 8;
        if (substr($addr, 0, $bytes) !== substr($netBin, 0, $bytes)) continue;
        if ($rest === 0) return true;
        $mask = (0xFF << (8 - $rest)) & 0xFF;
        if ((ord($addr[$bytes]) & $mask) === (ord($netBin[$bytes]) & $mask)) return true;
    }
    return false;
}

function ff_sync_epoch(PDO $db): string
{
    return (string)$db->query("SELECT v FROM meta WHERE k = 'epoch'")->fetchColumn();
}

function ff_sync_now(): int
{
    return (int)floor(microtime(true) * 1000);
}

function ff_sync_error(string $code, string $message, int $status): never
{
    ff_sync_json(['error' => ['code' => $code, 'message' => $message]], $status);
}

function ff_sync_json(array $payload, int $status = 200): never
{
    http_response_code($status);
    echo json_encode($payload, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
    exit;
}
